using namespace cute;
using ElementA = cutlass::half_t; using LayoutA = cutlass::layout::RowMajor;
using ElementB = cutlass::half_t; using LayoutB = cutlass::layout::ColumnMajor;
using ElementD = cutlass::half_t; using LayoutD = cutlass::layout::RowMajor;
using Acc = float;
using MmaTile = Shape<_256,_256,_64>; using Cluster = Shape<_2,_1,_1>;
using Epi = typename cutlass::epilogue::collective::CollectiveBuilder<
  cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, MmaTile, Cluster,
  cutlass::epilogue::collective::EpilogueTileAuto, Acc, Acc,
  void, LayoutD, 8, ElementD, LayoutD, 8, cutlass::epilogue::TmaWarpSpecialized2Sm>::CollectiveOp;
using Main = typename cutlass::gemm::collective::CollectiveBuilder<
  cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp,
  ElementA, LayoutA, 8, ElementB, LayoutB, 8, Acc, MmaTile, Cluster,
  cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename Epi::SharedStorage))>,
  cutlass::gemm::KernelTmaWarpSpecialized2SmSm100>::CollectiveOp;
using Kern = cutlass::gemm::kernel::GemmUniversal<Shape<int,int,int,int>, Main, Epi, void>;
using Gemm = cutlass::gemm::device::GemmUniversalAdapter<Kern>;
extern "C" int gemm_run(const void* A, const void* B, void* D, int M, void* stream) {
  int N = 5120, K = 2048;
  auto sA = cutlass::make_cute_packed_stride(typename Kern::StrideA{}, {M, K, 1});
  auto sB = cutlass::make_cute_packed_stride(typename Kern::StrideB{}, {N, K, 1});
  auto sD = cutlass::make_cute_packed_stride(typename Kern::StrideD{}, {M, N, 1});
  cutlass::KernelHardwareInfo hw; hw.device_id = 0; hw.sm_count = 148;
  typename Gemm::Arguments args{cutlass::gemm::GemmUniversalMode::kGemm, {M, N, K, 1},
    {(const ElementA*)A, sA, (const ElementB*)B, sB}, {{1.0f, 0.0f}, nullptr, sD, (ElementD*)D, sD}, hw};
  args.scheduler.raster_order = decltype(args.scheduler.raster_order)::AlongN;
  static Gemm g;
  if (g.can_implement(args) != cutlass::Status::kSuccess) return 1;
  if (g.initialize(args, nullptr, (cudaStream_t)stream) != cutlass::Status::kSuccess) return 2;
  return g.run((cudaStream_t)stream) != cutlass::Status::kSuccess;
}
'''
open('/tmp/c.cu','w').write(SRC)
r=subprocess.run('nvcc -shared -Xcompiler -fPIC -O3 -std=c++17 -gencode arch=compute_100a,code=sm_100a -I/usr/local/cutlass/include -I/usr/local/cutlass/tools/util/include /tmp/c.cu -o /tmp/c.so',shell=True,capture_output=True,text=True); print(r.returncode, r.stderr[-500:])
L=ctypes.CDLL('/tmp/c.so')
def cut(A,B,C):
    assert L.gemm_run(ctypes.c_void_p(A.data_ptr()),ctypes.c_void_p(B.data_ptr()),ctypes.c_void_p(C.data_ptr()),ctypes.c_int(A.shape[0]),ctypes.c_void_p(torch.cuda.current_stream().cuda_stream))==0
fns={'ref':lambda A,B,C: torch.matmul(A,B.T),'out':lambda A,B,C: torch.matmul(A,B.T,out=C),'cut':cut}
B=torch.randn(5120,2048,device='cuda',dtype=torch.half)
t0=time.time()
for M in [8828,16294]:
    A=torch.randn(M,2048,device='cuda',dtype=torch.half); C=torch.empty(M,5120,device='cuda',dtype=torch.half)
    res={k:[] for k in fns}
    order=['ref','out','cut','cut','out','ref','out','cut','ref']
    for k in order: res[k].append(b200probe.harness_time(fns[k],[A,B],[C]))
    print(M,{k:[round(x,1) for x in v] for k,v in res.items()},{k:round(sum(v)/len(v),1) for k,v in res.items()},flush=True)
print(round(time.time()-t0,1))

